return [
  { json: { categoryId: 'MLB1648', categoryName: 'informatica' } },
  { json: { categoryId: 'MLB1051', categoryName: 'celulares' } },
  { json: { categoryId: 'MLB1000', categoryName: 'eletronicos' } },
  { json: { categoryId: 'MLB1144', categoryName: 'games' } }
];

const crypto = require('crypto');
const affiliateTag = $env.ML_AFFILIATE_TAG || '';
const items = [];

for (const item of $input.all()) {
  const results = item.json.results || [];

  for (const product of results) {
    const mlId = product.id || '';
    const title = (product.title || '').slice(0, 500);
    const urlOriginal = product.permalink || '';
    const brand = product.brand || null;
    const priceCurrent = product.price || 0;
    const priceOriginal = product.original_price || null;
    const discountPct = priceOriginal && priceCurrent
      ? Math.round(((priceOriginal - priceCurrent) / priceOriginal) * 100)
      : null;
    const imageUrl = product.thumbnail?.replace('-I.jpg', '-O.jpg') || null;
    const condition = product.condition || '';

    if (priceCurrent <= 0 || !urlOriginal) continue;
    if (discountPct !== null && discountPct < 15) continue;

    const hashInput = (urlOriginal + mlId).toLowerCase().trim();
    const hashDedup = crypto.createHash('sha256').update(hashInput).digest('hex');

    items.push({
      json: {
        source: 'mercadolivre',
        external_id: mlId,
        hash_dedup: hashDedup,
        title,
        url_original: urlOriginal,
        store: 'mercadolivre',
        brand,
        price_current: priceCurrent,
        price_original: priceOriginal,
        discount_pct: discountPct,
        image_url: imageUrl,
        raw_payload: { id: mlId, title, price: priceCurrent, original_price: priceOriginal, condition },
      }
    });
  }
}

return items;
